// Agent-facing manifest for palette mesh variants (from qfp-variants.glb).
// Generated by scripts/export-mesh-variant-catalog.ts — do not hand-edit.

import type { MeshKind } from "./circuitMeshBoxes";
import { MESH_LABELS } from "./circuitMeshBoxes";
import type { MeshSize } from "./circuitMeshes";
import { DEFAULT_MESH_SIZE } from "./circuitMeshes";
import type { VariantCatalog } from "./qfpVariantCatalog";

export type MeshVariantManifestEntry = {
  id: string;
  label: string;
  kind: MeshKind;
  categoryLabel: string;
  index: number;
  placeSize: MeshSize;
  natural: { w: number; d: number; h: number };
};

export type MeshVariantManifest = {
  generatedAt: string;
  sourceGlb: string;
  note: string;
  defaultMeshSize: Record<MeshKind, MeshSize>;
  /** Palette label or variant id → canonical variant id. */
  lookup: Record<string, string>;
  categories: Array<{
    kind: MeshKind;
    label: string;
    variantIds: string[];
  }>;
  variants: MeshVariantManifestEntry[];
  meshEditsExample: {
    id: string;
    kind: MeshKind;
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
    variant: string;
  };
};

export function serializeVariantCatalogForAgent(
  catalog: VariantCatalog,
  opts?: { generatedAt?: string; sourceGlb?: string },
): MeshVariantManifest {
  const lookup: Record<string, string> = {};
  const variants: MeshVariantManifestEntry[] = [];

  for (const cat of catalog.categories) {
    for (const v of cat.variants) {
      lookup[v.id] = v.id;
      lookup[v.label] = v.id;
      variants.push({
        id: v.id,
        label: v.label,
        kind: v.kind,
        categoryLabel: cat.label,
        index: v.index,
        placeSize: v.placeSize,
        natural: v.natural,
      });
    }
  }

  const example = variants.find((v) => v.label === "QFP 3") ?? variants[0];
  const { w, h } = example?.placeSize ?? DEFAULT_MESH_SIZE.qfp;
  const cx = 12;
  const cz = 6;

  return {
    generatedAt: opts?.generatedAt ?? new Date().toISOString(),
    sourceGlb: opts?.sourceGlb ?? "public/models/qfp-variants.glb",
    note:
      "Resolve a palette label (e.g. QFP 3) via lookup, then append to meshEdits.added in circuits-tuning.json or circuit-versions/N.json. Or run: pnpm run insert-circuit-mesh -- --variant \"QFP 3\" --at 12,6",
    defaultMeshSize: { ...DEFAULT_MESH_SIZE },
    lookup,
    categories: catalog.categories.map((cat) => ({
      kind: cat.kind,
      label: cat.label,
      variantIds: cat.variants.map((v) => v.id),
    })),
    variants,
    meshEditsExample: {
      id: "mesh-user-41",
      kind: example?.kind ?? "qfp",
      minX: cx - w / 2,
      maxX: cx + w / 2,
      minZ: cz - h / 2,
      maxZ: cz + h / 2,
      variant: example?.id ?? "q3-plain-prism",
    },
  };
}

export function bboxFromCenter(
  cx: number,
  cz: number,
  size: MeshSize,
): { minX: number; maxX: number; minZ: number; maxZ: number } {
  const { w, h } = size;
  return {
    minX: cx - w / 2,
    maxX: cx + w / 2,
    minZ: cz - h / 2,
    maxZ: cz + h / 2,
  };
}

function normalizeRef(ref: string): string {
  return ref.trim().replace(/\s+/g, " ");
}

/** Resolve a palette label ("QFP 3") or variant id ("q3-plain-prism"). */
export function resolveVariantRef(
  manifest: MeshVariantManifest,
  ref: string,
): MeshVariantManifestEntry {
  const key = normalizeRef(ref);
  const id = manifest.lookup[key];
  if (id) {
    const hit = manifest.variants.find((v) => v.id === id);
    if (hit) return hit;
  }

  const lower = key.toLowerCase();
  const byLabel = manifest.variants.find(
    (v) => v.label.toLowerCase() === lower,
  );
  if (byLabel) return byLabel;

  const byId = manifest.variants.find((v) => v.id.toLowerCase() === lower);
  if (byId) return byId;

  const suggestions = manifest.variants
    .filter((v) => v.label.toLowerCase().includes(lower) || v.id.includes(lower))
    .slice(0, 5)
    .map((v) => v.label);

  const hint =
    suggestions.length > 0
      ? ` Did you mean: ${suggestions.join(", ")}?`
      : ` Known labels include: ${manifest.variants.slice(0, 5).map((v) => v.label).join(", ")}…`;

  throw new Error(`Unknown mesh variant "${ref}".${hint}`);
}

export function formatVariantSummary(v: MeshVariantManifestEntry): string {
  return `${v.label} (${v.id}, kind=${v.kind}, footprint ${v.placeSize.w}×${v.placeSize.h})`;
}

export function categoryLabelForKind(kind: MeshKind): string {
  return MESH_LABELS[kind] ?? kind;
}
